# ОФЛАЙН-ПЕРЕВОДЧИК WORD2WORD (en → ru)
# ============================================================
_WORD2WORD_EN2RU = None

def _init_word2word():
    """Загружает словарь en→ru один раз при старте. Офлайн после загрузки."""
    global _WORD2WORD_EN2RU
    if _WORD2WORD_EN2RU is not None:
        return True
    try:
        from word2word import Word2word
        logger.info("[WORD2WORD] Загрузка словаря en→ru...")
        _WORD2WORD_EN2RU = Word2word("en", "ru")
        logger.info("[WORD2WORD] Словарь загружен")
        return True
    except Exception as e:
        logger.error(f"[WORD2WORD] Ошибка инициализации: {e}")
        return False


def _word2word_translate_ru(text):
    """Грубый дословный перевод en→ru. Берёт первый (самый частый) вариант."""
    if not text:
        return text
    if _WORD2WORD_EN2RU is None:
        return text
    import re
    tokens = re.split(r'(\W+)', text)
    result = []
    for tok in tokens:
        if not tok or not re.match(r'^\w+$', tok):
            result.append(tok)
            continue
        low = tok.lower()
        try:
            variants = _WORD2WORD_EN2RU(low)
            if variants:
                ru = variants[0]
                if tok[0].isupper():
                    ru = ru.capitalize()
                result.append(ru)
            else:
                result.append(tok)
        except Exception:
            result.append(tok)
    return ''.join(result)

