_ARGOS_INITIALIZED = False
_ARGOS_LANG_MAP = {
    'en': 'en', 'ru': 'ru', 'zh-CN': 'zh', 'zh': 'zh',
}

def _init_argos():
    """Ставит все нужные пакеты Argos один раз при старте."""
    global _ARGOS_INITIALIZED
    if _ARGOS_INITIALIZED:
        return True
    try:
        import argostranslate.package
        argostranslate.package.update_package_index()
        available = argostranslate.package.get_available_packages()
        installed = argostranslate.package.get_installed_packages()
        installed_pairs = {(p.from_code, p.to_code) for p in installed}

        needed = [('en', 'ru'), ('en', 'zh'), ('ru', 'en'), ('zh', 'en')]
        for src, dst in needed:
            if (src, dst) in installed_pairs:
                continue
            pkg = next((p for p in available
                        if p.from_code == src and p.to_code == dst), None)
            if pkg:
                logger.info(f"[ARGOS] Устанавливаю {src}→{dst}...")
                argostranslate.package.install_from_path(pkg.download())
                logger.info(f"[ARGOS] {src}→{dst} установлен")
            else:
                logger.warning(f"[ARGOS] Пакет {src}→{dst} не найден")

        _ARGOS_INITIALIZED = True
        logger.info("[ARGOS] Инициализация завершена")
        return True
    except Exception as e:
        logger.error(f"[ARGOS] Ошибка инициализации: {e}", exc_info=True)
        return False


def _argos_translate(text, source_lang, target_lang):
    """Офлайн-перевод. Возвращает строку или None."""
    if not text:
        return None
    try:
        import argostranslate.translate
        src = _ARGOS_LANG_MAP.get(source_lang, source_lang)
        dst = _ARGOS_LANG_MAP.get(target_lang, target_lang)
        if src == dst:
            return None
        result = argostranslate.translate.translate(text, src, dst)
        if result and result != text:
            return result
        return None
    except Exception as e:
        logger.debug(f"[ARGOS] Ошибка {source_lang}→{target_lang}: {e}")
        return None

