TRANSLATION_BAN_FILE = "TRANSLATION_BAN.json"
TRANSLATION_BAN_HOURS = 24


def _load_translation_ban():
    """Возвращает (is_banned, banned_until, remaining_seconds)."""
    try:
        if os.path.exists(TRANSLATION_BAN_FILE):
            with open(TRANSLATION_BAN_FILE, 'r', encoding='utf-8') as f:
                data = json.load(f)
            banned_until_str = data.get('banned_until', '')
            if banned_until_str:
                banned_until = datetime.fromisoformat(banned_until_str)
                now = datetime.now()
                if now < banned_until:
                    remaining = (banned_until - now).total_seconds()
                    return True, banned_until, remaining
                else:
                    try:
                        os.remove(TRANSLATION_BAN_FILE)
                    except Exception:
                        pass
    except Exception as e:
        logger.warning(f"[TRANSLATE-BAN] Ошибка чтения файла бана: {e}")
    return False, None, 0


def _set_translation_ban(hours=TRANSLATION_BAN_HOURS,
                         reason="Google antibot / rate limit"):
    """Устанавливает бан перевода на указанное число часов."""
    try:
        banned_until = datetime.now() + timedelta(hours=hours)
        data = {
            'banned_until': banned_until.isoformat(),
            'reason': reason,
            'set_at': datetime.now().isoformat(),
        }
        with open(TRANSLATION_BAN_FILE, 'w', encoding='utf-8') as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        logger.warning(
            f"[TRANSLATE-BAN] ⛔ Установлен бан перевода до {banned_until} "
            f"({hours} ч). Причина: {reason}"
        )
        return True
    except Exception as e:
        logger.error(f"[TRANSLATE-BAN] Ошибка записи файла бана: {e}")
        return False


def _is_translation_banned():
    """Быстрая проверка: (is_banned, remaining_seconds)."""
    is_banned, _, remaining = _load_translation_ban()
    return is_banned, remaining


def _detect_ban_error(err_text: str) -> bool:
    """Распознаёт ошибку антибота Google."""
    if not err_text:
        return False
    low = str(err_text).lower()
    markers = [
        'too many requests',
        '5 requests per second',
        'server error',
        '429',
        'you made too many requests',
        'allowed to make 5 requests',
    ]
    return any(m in low for m in markers)

