# ============================================================
# СОСТОЯНИЕ LIBRETRANSLATE (кэши + cooldown)
# ============================================================
# Живые инстансы (успешно ответили хотя бы раз)
_LIBRETRANSLATE_WORKING = []
# Мёртвые (404, 500, connection error) — больше не пробуем
_LIBRETRANSLATE_DEAD = set()
# Cooldown после 429/403: {url: until_timestamp}
_LIBRETRANSLATE_COOLDOWN = {}
# Чтобы не спамить в лог одну и ту же 429 — {url: last_log_ts}
_LIBRETRANSLATE_429_LAST_LOG = {}

_LIBRETRANSLATE_COOLDOWN_SECONDS = 300   # 5 минут остывания после 429
_LIBRETRANSLATE_MIN_INTERVAL = 0.6       # глобальный троттлинг между запросами
_LIBRETRANSLATE_LAST_REQUEST_TIME = 0.0


def _libretranslate_text(text, source, target, timeout=5):
    """
    Прямой вызов LibreTranslate API через requests.
    Пробует несколько публичных инстансов (open-source, НЕ Google).
    Возвращает переведённый текст или None.

    Логика:
      • 200 + валидный ответ      → кэшируем URL как рабочий, возвращаем перевод
      • 200 + ERROR_MARKER        → считаем инстанс мёртвым (INVALID SOURCE LANGUAGE и др.)
      • 429                       → cooldown на 5 мин, убираем из WORKING, в лог пишем
                                    ТОЛЬКО ОДИН РАЗ за окно cooldown
      • 403                       → cooldown 60 сек (иногда это тоже rate-limit)
      • 404/500/502/503/504       → считаем мёртвым навсегда
      • Exception (timeout и др.) → считаем мёртвым навсегда
      • Все инстансы в cooldown   → сразу возвращаем None (MyMemory подхватит)

    Глобальный троттлинг: не чаще 1 запроса в _LIBRETRANSLATE_MIN_INTERVAL сек.
    """
    global _LIBRETRANSLATE_LAST_REQUEST_TIME

    if not text:
        return None

    import requests
    import time as _time

    now = _time.time()

    # --- Глобальный троттлинг между запросами ---
    elapsed = now - _LIBRETRANSLATE_LAST_REQUEST_TIME
    if elapsed < _LIBRETRANSLATE_MIN_INTERVAL:
        _time.sleep(_LIBRETRANSLATE_MIN_INTERVAL - elapsed)

    lt_target = LIBRETRANSLATE_LANG_MAP.get(target, target)
    lt_source = LIBRETRANSLATE_LANG_MAP.get(source, source) if source else 'en'
    if not lt_source or lt_source == 'auto':
        lt_source = 'en'

    payload = {
        'q': text,
        'source': lt_source,
        'target': lt_target,
        'format': 'text',
    }

    # --- Чистим истёкшие cooldown ---
    now = _time.time()
    expired = [u for u, until in _LIBRETRANSLATE_COOLDOWN.items() if now >= until]
    for u in expired:
        _LIBRETRANSLATE_COOLDOWN.pop(u, None)
        _LIBRETRANSLATE_429_LAST_LOG.pop(u, None)

    # --- Формируем список кандидатов: сначала рабочие, потом все остальные ---
    candidates = []
    seen = set()

    for u in _LIBRETRANSLATE_WORKING:
        if u in _LIBRETRANSLATE_DEAD:
            continue
        if u in _LIBRETRANSLATE_COOLDOWN:
            continue
        candidates.append(u)
        seen.add(u)

    for u in LIBRETRANSLATE_INSTANCES:
        if u in seen:
            continue
        if u in _LIBRETRANSLATE_DEAD:
            continue
        if u in _LIBRETRANSLATE_COOLDOWN:
            continue
        candidates.append(u)

    if not candidates:
        # Все инстансы либо мёртвы, либо в cooldown. Не тратим время.
        return None

    ERROR_MARKERS = (
        'INVALID SOURCE LANGUAGE',
        'ALMOST ALL LANGUAGES SUPPORTED',
        'LANGPAIR=',
    )

    for url in candidates:
        try:
            _LIBRETRANSLATE_LAST_REQUEST_TIME = _time.time()
            r = requests.post(f"{url}/translate", json=payload, timeout=timeout)

            if r.status_code == 200:
                data = r.json()
                result = data.get('translatedText', '') or ''
                upper = result.upper()
                if any(marker in upper for marker in ERROR_MARKERS):
                    logger.warning(
                        f"[LT] ⚠️ {url} вернул сообщение об ошибке вместо перевода: "
                        f"{result[:80]}"
                    )
                    _LIBRETRANSLATE_DEAD.add(url)
                    continue
                if result:
                    if url not in _LIBRETRANSLATE_WORKING:
                        _LIBRETRANSLATE_WORKING.append(url)
                        logger.warning(f"[LT] ✅ Рабочий инстанс LibreTranslate: {url}")
                    return result

            elif r.status_code == 429:
                # Rate limit — временный cooldown, НЕ в DEAD
                until = _time.time() + _LIBRETRANSLATE_COOLDOWN_SECONDS
                _LIBRETRANSLATE_COOLDOWN[url] = until
                # Убираем из WORKING — он перегружен
                if url in _LIBRETRANSLATE_WORKING:
                    _LIBRETRANSLATE_WORKING.remove(url)
                # Логируем ТОЛЬКО ОДИН РАЗ за окно cooldown, чтобы не спамить
                last_log = _LIBRETRANSLATE_429_LAST_LOG.get(url, 0)
                if _time.time() - last_log > _LIBRETRANSLATE_COOLDOWN_SECONDS:
                    logger.warning(
                        f"[LT] ⏸️ {url} вернул 429, cooldown "
                        f"{_LIBRETRANSLATE_COOLDOWN_SECONDS} сек"
                    )
                    _LIBRETRANSLATE_429_LAST_LOG[url] = _time.time()
                continue

            elif r.status_code == 403:
                # Иногда 403 — это тоже rate limit у Cloudflare
                until = _time.time() + 60
                _LIBRETRANSLATE_COOLDOWN[url] = until
                if url in _LIBRETRANSLATE_WORKING:
                    _LIBRETRANSLATE_WORKING.remove(url)
                last_log = _LIBRETRANSLATE_429_LAST_LOG.get(url, 0)
                if _time.time() - last_log > 60:
                    logger.warning(f"[LT] ⏸️ {url} вернул 403, cooldown 60 сек")
                    _LIBRETRANSLATE_429_LAST_LOG[url] = _time.time()
                continue

            else:
                logger.warning(f"[LT] ⚠️ {url} вернул статус {r.status_code}")
                if r.status_code in (404, 500, 502, 503, 504):
                    _LIBRETRANSLATE_DEAD.add(url)
                continue

        except Exception as e:
            logger.warning(f"[LT] ❌ {url} недоступен: {e}")
            _LIBRETRANSLATE_DEAD.add(url)
            continue

    return None

def _my_memory_translate(translator, text):
    """Обёртка для MyMemory с защитой от ошибок."""
    if not text:
        return text
    try:
        result = translator.translate(text)
        return result if result else text
    except Exception as e:
        logger.debug(f"[MYMEMORY] Ошибка: {e}")
        return text

