class MultiLangTranslationWorker(QtCore.QThread):
        """
        Воркер перевода. Принимает список кортежей (url, title) и возвращает
        список словарей вида:
            [{'url': ..., 'title': ..., 'translations': {'ru': ..., 'zh-CN': ...}}, ...]
        Это исключает коллизии при одинаковых заголовках и позволяет
        обрабатывать несколько воркеров одновременно без общей переменной URL.
        Перевод выполняется офлайн через Argos Translate.
        """
        finished_signal = QtCore.pyqtSignal(list)
        error_signal = QtCore.pyqtSignal(str)
        progress_signal = QtCore.pyqtSignal(int, int)

        def __init__(self, items, target_langs=None, batch_size=50, source_lang='en'):
            super().__init__()
            # items: список кортежей (url, title)
            self.items = items
            self.target_langs = target_langs if target_langs else ['ru', 'zh-CN']
            self.batch_size = batch_size
            self.source_lang = source_lang
            self._start_time = None
            self._is_running = True

        def run(self):
            try:
                _init_argos()
                self._start_time = time.time()
                results = []
                total = len(self.items)
                processed = 0

                if total == 0:
                    self.finished_signal.emit([])
                    return

                self.progress_signal.emit(0, total)

                for url, title in self.items:
                    if not self._is_running:
                        break
                    translations = {}
                    for lang in self.target_langs:
                        if not title:
                            translations[lang] = ''
                            continue
                        tr = _argos_translate(title, self.source_lang, lang)
                        translations[lang] = tr if tr else title

                    results.append({
                        'url': url,
                        'title': title,
                        'translations': translations
                    })
                    processed += 1
                    self.progress_signal.emit(processed, total)

                logger.info(
                    f"[TRANSLATE-ARGOS] Готово: {processed}/{total}, "
                    f"время={time.time() - self._start_time:.1f} сек"
                )
                self.finished_signal.emit(results)
            except Exception as e:
                logger.error(f"[TRANSLATE-ARGOS] Критическая ошибка: {e}", exc_info=True)
                self.error_signal.emit(str(e))

class MatcherShiftedWorker(QtCore.QThread):
    finished_signal = QtCore.pyqtSignal(list)  # обновлённый список результатов
    error_signal = QtCore.pyqtSignal(str)
    progress_signal = QtCore.pyqtSignal(int, int)
    status_signal = QtCore.pyqtSignal(str)
    log_signal = QtCore.pyqtSignal(str)

    def __init__(self, ch_config, results, target_timeframes=None):
        super().__init__()
        self.ch_config = ch_config
        self.results = results  # список словарей от MatcherTestWorker
        self.target_tfs = target_timeframes or ['1h', '30m']
        self._client = None
        self._is_running = True

    def run(self):
        try:
            self._client = ClickHouseClient(
                host=self.ch_config['host'],
                port=self.ch_config['port'],
                user=self.ch_config['user'],
                password=self.ch_config['password'],
                settings={'insert_block_size': 10000, 'connect_timeout': 30}
            )
            self.log_signal.emit("[SHIFTED] Загрузка сдвинутых точек и цен...")

            # 1. Загружаем shifted_points для каждого ТФ
            shifted_cache = {}  # {tf: {shift_type: [timestamp, ...]}}
            price_cache = {}     # {tf: {timestamp: close}}

            for tf in self.target_tfs:
                # shifted_points
                query = f"""
                    SELECT timestamp, shift_type
                    FROM crypto_data.shifted_points
                    WHERE timeframe = '{tf}'
                """
                rows = self._client.execute(query)
                tf_shifted = {}
                for ts, stype in rows:
                    tf_shifted.setdefault(stype, []).append(ts)
                shifted_cache[tf] = tf_shifted

                # цены закрытия
                query_price = f"""
                    SELECT timestamp, close
                    FROM crypto_data.btc_usdt_{tf}
                """
                price_rows = self._client.execute(query_price)
                tf_prices = {row[0]: float(row[1]) for row in price_rows}
                price_cache[tf] = tf_prices

                self.log_signal.emit(f"[SHIFTED] Загружено {len(rows)} shifted для {tf}, {len(price_rows)} цен")

            # 2. Для каждого результата ищем сдвинутые точки
            total = len(self.results)
            for idx, res in enumerate(self.results):
                if not self._is_running:
                    break
                position = res['position']
                direction = res['direction']
                start_dt = res.get('start_dt')
                end_dt = res.get('end_dt')
                targets = res.get('targets', {})

                for tf in self.target_tfs:
                    tf_data = targets.get(tf, {})
                    first_ts = tf_data.get('first_ts')
                    second_ts = tf_data.get('second_ts')

                    # Определяем типы сдвинутых точек
                    if direction == 'long':
                        start_type = 'long_start'
                        end_type = 'long_end'
                    else:  # short
                        start_type = 'short_start'
                        end_type = 'short_end'

                    # ---- Поиск первой сдвинутой точки ----
                    if first_ts is not None:
                        # используем пересечение как цель (влево)
                        shifted1 = self._find_nearest_shifted(
                            shifted_cache[tf].get(start_type, []),
                            first_ts,
                            price_cache[tf],
                            tf,
                            max_bars=3,
                            search_direction='left'
                        )
                    else:
                        # fallback: ищем по start_dt (9 часов в обе стороны)
                        self.log_signal.emit(
                            f"[SHIFTED] Позиция {position}, ТФ {tf}: first_ts не найден, "
                            f"используем fallback от start_dt {start_dt}"
                        )
                        if start_dt:
                            shifted1 = self._find_nearest_shifted(
                                shifted_cache[tf].get(start_type, []),
                                start_dt,
                                price_cache[tf],
                                tf,
                                max_bars=9 * 60 // self._tf_minutes(tf),
                                search_direction='both'
                            )
                        else:
                            shifted1 = None

                    # ---- Поиск второй сдвинутой точки ----
                    if second_ts is not None:
                        shifted2 = self._find_nearest_shifted(
                            shifted_cache[tf].get(end_type, []),
                            second_ts,
                            price_cache[tf],
                            tf,
                            max_bars=3,
                            search_direction='right'
                        )
                    else:
                        self.log_signal.emit(
                            f"[SHIFTED] Позиция {position}, ТФ {tf}: second_ts не найден, "
                            f"используем fallback от end_dt {end_dt}"
                        )
                        if end_dt:
                            shifted2 = self._find_nearest_shifted(
                                shifted_cache[tf].get(end_type, []),
                                end_dt,
                                price_cache[tf],
                                tf,
                                max_bars=9 * 60 // self._tf_minutes(tf),
                                search_direction='both'
                            )
                        else:
                            shifted2 = None

                    # Сохраняем результаты
                    tf_data['shifted1_ts'] = shifted1[0] if shifted1 else None
                    tf_data['shifted1_price'] = shifted1[1] if shifted1 else None
                    tf_data['shifted2_ts'] = shifted2[0] if shifted2 else None
                    tf_data['shifted2_price'] = shifted2[1] if shifted2 else None

                    targets[tf] = tf_data

                self.progress_signal.emit(idx+1, total)
                self.status_signal.emit(f"Обработано {idx+1}/{total}")

            self.finished_signal.emit(self.results)

        except Exception as e:
            self.error_signal.emit(str(e))
            import traceback
            self.log_signal.emit(traceback.format_exc())
        finally:
            if self._client:
                try:
                    self._client.disconnect()
                except:
                    pass

    def _tf_minutes(self, tf):
        """Возвращает количество минут в таймфрейме."""
        return {'30m': 30, '1h': 60, '4h': 240}.get(tf, 60)

    def _find_nearest_shifted(self, timestamps, target_ts, price_dict, tf, max_bars=3, search_direction='both'):
        """
        Ищет ближайшую по времени сдвинутую точку из списка timestamps
        в пределах max_bars свечей.
        search_direction: 'left' - только <= target_ts, 'right' - только >= target_ts, 'both' - обе стороны.
        Возвращает (timestamp, price) или None.
        """
        if not timestamps:
            return None
        tf_minutes = self._tf_minutes(tf)
        delta_sec = max_bars * tf_minutes * 60

        best_ts = None
        best_diff = float('inf')
        for ts in timestamps:
            diff = (ts - target_ts).total_seconds()
            if search_direction == 'left':
                if diff > 0 or diff < -delta_sec:
                    continue
            elif search_direction == 'right':
                if diff < 0 or diff > delta_sec:
                    continue
            else:
                if abs(diff) > delta_sec:
                    continue
            if abs(diff) < best_diff:
                best_diff = abs(diff)
                best_ts = ts
        if best_ts is None:
            return None
        price = price_dict.get(best_ts)
        if price is None:
            price = self._get_nearest_price(price_dict, best_ts)
        return (best_ts, price) if price is not None else None

    def _get_nearest_price(self, price_dict, ts):
        """Возвращает цену ближайшей свечи (если точная не найдена)."""
        if ts in price_dict:
            return price_dict[ts]
        import bisect
        keys = sorted(price_dict.keys())
        idx = bisect.bisect_left(keys, ts)
        candidates = []
        if idx < len(keys):
            candidates.append(keys[idx])
        if idx > 0:
            candidates.append(keys[idx-1])
        if not candidates:
            return None
        best = min(candidates, key=lambda x: abs((x - ts).total_seconds()))
        return price_dict[best]

    def stop(self):
        self._is_running = False

class ShiftedResultsDialog(QtWidgets.QDialog):
    def __init__(self, results, parent=None, manual_pairs=None, main_app=None):
        super().__init__(parent)
        self.setWindowTitle("Результаты сопоставления со сдвинутыми точками")
        self.setMinimumSize(1500, 700)
        self.setModal(False)
        self.results = results
        self.main_app = main_app
        layout = QtWidgets.QVBoxLayout(self)

        self.manual_pairs = manual_pairs if manual_pairs else {}

        table = QtWidgets.QTableWidget()
        table.setColumnCount(17)
        table.setHorizontalHeaderLabels([
            "Позиция", "Напр.", "ТФ",
            "Пер.1 (время)", "Пер.1 (цена)",
            "Пер.2 (время)", "Пер.2 (цена)",
            "Сдв.1 (время)", "Сдв.1 (цена)",
            "Сдв.2 (время)", "Сдв.2 (цена)",
            "Ручная 1h нач", "Ручная 1h кон",
            "Ручная 30m нач", "Ручная 30m кон",
            "Статус 1", "Статус 2"
        ])
        table.horizontalHeader().setStretchLastSection(True)

        manual_1h = self.manual_pairs.get('1h', [])
        manual_30m = self.manual_pairs.get('30m', [])

        row = 0
        for res in results:
            pos = res['position']
            direction = res['direction']
            targets = res.get('targets', {})
            for tf in ['1h', '30m']:
                data = targets.get(tf)
                if not data:
                    continue
                table.insertRow(row)

                table.setItem(row, 0, QtWidgets.QTableWidgetItem(str(pos)))
                table.setItem(row, 1, QtWidgets.QTableWidgetItem(direction))
                table.setItem(row, 2, QtWidgets.QTableWidgetItem(tf))

                first_ts = data.get('first_ts')
                first_price = data.get('first_price')
                second_ts = data.get('second_ts')
                second_price = data.get('second_price')
                table.setItem(row, 3, QtWidgets.QTableWidgetItem(first_ts.strftime('%Y-%m-%d %H:%M') if first_ts else ''))
                table.setItem(row, 4, QtWidgets.QTableWidgetItem(f"{first_price:.2f}" if first_price else ''))
                table.setItem(row, 5, QtWidgets.QTableWidgetItem(second_ts.strftime('%Y-%m-%d %H:%M') if second_ts else ''))
                table.setItem(row, 6, QtWidgets.QTableWidgetItem(f"{second_price:.2f}" if second_price else ''))

                shifted1_ts = data.get('shifted1_ts')
                shifted1_price = data.get('shifted1_price')
                shifted2_ts = data.get('shifted2_ts')
                shifted2_price = data.get('shifted2_price')
                table.setItem(row, 7, QtWidgets.QTableWidgetItem(shifted1_ts.strftime('%Y-%m-%d %H:%M') if shifted1_ts else ''))
                table.setItem(row, 8, QtWidgets.QTableWidgetItem(f"{shifted1_price:.2f}" if shifted1_price else ''))
                table.setItem(row, 9, QtWidgets.QTableWidgetItem(shifted2_ts.strftime('%Y-%m-%d %H:%M') if shifted2_ts else ''))
                table.setItem(row, 10, QtWidgets.QTableWidgetItem(f"{shifted2_price:.2f}" if shifted2_price else ''))

                # Ручные пары
                if tf == '1h':
                    manual_list = manual_1h
                else:
                    manual_list = manual_30m

                if pos <= len(manual_list):
                    dt1, _, dt2, _, _, _ = manual_list[pos-1]
                    if tf == '1h':
                        table.setItem(row, 11, QtWidgets.QTableWidgetItem(dt1.strftime('%Y-%m-%d %H:%M')))
                        table.setItem(row, 12, QtWidgets.QTableWidgetItem(dt2.strftime('%Y-%m-%d %H:%M')))
                        table.setItem(row, 13, QtWidgets.QTableWidgetItem(''))
                        table.setItem(row, 14, QtWidgets.QTableWidgetItem(''))
                    else:  # 30m
                        table.setItem(row, 13, QtWidgets.QTableWidgetItem(dt1.strftime('%Y-%m-%d %H:%M')))
                        table.setItem(row, 14, QtWidgets.QTableWidgetItem(dt2.strftime('%Y-%m-%d %H:%M')))
                        table.setItem(row, 11, QtWidgets.QTableWidgetItem(''))
                        table.setItem(row, 12, QtWidgets.QTableWidgetItem(''))
                else:
                    table.setItem(row, 11, QtWidgets.QTableWidgetItem(''))
                    table.setItem(row, 12, QtWidgets.QTableWidgetItem(''))
                    table.setItem(row, 13, QtWidgets.QTableWidgetItem(''))
                    table.setItem(row, 14, QtWidgets.QTableWidgetItem(''))

                status1 = "Найдено" if shifted1_ts else "Не найдено"
                status2 = "Найдено" if shifted2_ts else "Не найдено"
                table.setItem(row, 15, QtWidgets.QTableWidgetItem(status1))
                table.setItem(row, 16, QtWidgets.QTableWidgetItem(status2))

                # Подсветка совпадений с ручными парами
                if pos <= len(manual_list):
                    manual_start = manual_list[pos-1][0]
                    manual_end = manual_list[pos-1][2]
                    if shifted1_ts:
                        if shifted1_ts.strftime('%Y-%m-%d %H:%M') == manual_start.strftime('%Y-%m-%d %H:%M'):
                            item = table.item(row, 7)
                            if item:
                                item.setBackground(QtGui.QColor(0, 255, 0, 77))
                    if shifted2_ts:
                        if shifted2_ts.strftime('%Y-%m-%d %H:%M') == manual_end.strftime('%Y-%m-%d %H:%M'):
                            item = table.item(row, 9)
                            if item:
                                item.setBackground(QtGui.QColor(0, 255, 0, 77))

                row += 1

        table.resizeColumnsToContents()
        layout.addWidget(table)

        # Кнопка перезаписи ручных пар
        btn_rewrite = QtWidgets.QPushButton("Переписать ручные пары (только несовпадающие)")
        btn_rewrite.setStyleSheet("background-color: #2E7D32; color: white; font-weight: bold;")
        btn_rewrite.clicked.connect(self._on_rewrite)
        layout.addWidget(btn_rewrite)

        # ===== НОВАЯ КНОПКА ДЛЯ ЗАПИСИ В БД =====
        btn_save_to_db = QtWidgets.QPushButton("💾 Записать авто-ID в БД (1h/30m)")
        btn_save_to_db.setStyleSheet("background-color: #1E3A5F; color: white; font-weight: bold;")
        btn_save_to_db.clicked.connect(self._on_save_to_db)
        layout.addWidget(btn_save_to_db)

        btn_close = QtWidgets.QPushButton("Закрыть")
        btn_close.clicked.connect(self.accept)
        layout.addWidget(btn_close)

    def _on_save_to_db(self):
        """Обработчик нажатия кнопки записи в БД."""
        if self.main_app and hasattr(self.main_app, 'save_shifted_to_auto_ids'):
            self.main_app.save_shifted_to_auto_ids(self.results)
        else:
            QtWidgets.QMessageBox.warning(self, "Ошибка", "Не удалось вызвать метод сохранения в БД.")        

    def _on_rewrite(self):
        if self.main_app and hasattr(self.main_app, 'rewrite_time_pairs_from_shifted'):
            self.main_app.rewrite_time_pairs_from_shifted(self.results)
        else:
            QtWidgets.QMessageBox.warning(self, "Ошибка", "Не удалось вызвать метод перезаписи.")

class GapDetectorWorker(QtCore.QThread):
    """
    Поиск разрывов в инкрементальном обновлении: для заданного таймфрейма
    находит все временные метки из shifted_points, для которых нет ID
    с таким же start_time в auto_ids. Возвращает информацию о пропусках.
    """
    finished_signal = QtCore.pyqtSignal(dict)
    error_signal = QtCore.pyqtSignal(str)
    status_signal = QtCore.pyqtSignal(str)
    progress_signal = QtCore.pyqtSignal(int, int)  # не используется, но оставлен для совместимости

    def __init__(self, ch_client, timeframe):
        """
        ch_client: клиент ClickHouse
        timeframe: '30m', 45m', '1h', '4h'
        """
        super().__init__()
        self.ch_client = ch_client
        self.timeframe = timeframe
        self._is_running = True

    def run(self):
        """
        Выполняет запрос и возвращает результат.
        """
        try:
            self.status_signal.emit(f"Поиск разрывов для {self.timeframe}...")
            start_time = time.time()

            # Строим запрос – только проверка на точное совпадение start_time
            query = f"""
                SELECT timestamp
                FROM crypto_data.shifted_points
                WHERE timeframe = '{self.timeframe}'
                  AND timestamp NOT IN (
                      SELECT start_time
                      FROM crypto_data.auto_ids
                      WHERE timeframe = '{self.timeframe}'
                  )
                ORDER BY timestamp
            """

            self.status_signal.emit(f"Выполнение запроса для {self.timeframe}...")
            rows = self.ch_client.execute(query)
            timestamps = [row[0] for row in rows]
            count = len(timestamps)

            elapsed = time.time() - start_time
            logger.info(f"[GapDetector] {self.timeframe}: найдено {count} пропусков за {elapsed:.2f} сек")

            result = {
                'timeframe': self.timeframe,
                'count': count,
                'first': timestamps[0] if count else None,
                'last': timestamps[-1] if count else None,
                'timestamps': timestamps,  # список всех меток (может быть большим, но для 4h это ~7.5k)
                'elapsed': elapsed
            }

            self.status_signal.emit(f"Готово для {self.timeframe}: {count} пропусков")
            self.finished_signal.emit(result)

        except Exception as e:
            logger.error(f"[GapDetector] Ошибка для {self.timeframe}: {str(e)}", exc_info=True)
            self.error_signal.emit(str(e))
        finally:
            self._is_running = False

    def stop(self):
        """Остановка воркера (если нужно прервать долгий запрос)"""
        self._is_running = False
        logger.info(f"[GapDetector] Остановка для {self.timeframe}")

class TeeLogger:
    """Дублирует stdout/stderr в консоль и в файл (файл перезаписывается)"""
    def __init__(self, filename):
        self.terminal_stdout = sys.__stdout__   # оригинальный stdout
        self.terminal_stderr = sys.__stderr__   # оригинальный stderr
        self.log_file = open(filename, 'w', encoding='utf-8')

    def write(self, message):
        self.terminal_stdout.write(message)
        self.log_file.write(message)
        self.log_file.flush()

    def flush(self):
        self.terminal_stdout.flush()
        self.log_file.flush()

    def close(self):
        self.log_file.close()

def setup_session_logging(log_filename="session.log"):
    tee = TeeLogger(log_filename)
    sys.stdout = tee
    sys.stderr = tee
    # Печатаем тестовое сообщение, чтобы убедиться, что файл пишется
    print(f"[LOG] Логирование включено. Файл: {log_filename}")
    return tee

def compute_dcm_from_seconds(idx1, idx2, tf_minutes):
    """
    idx1, idx2: start_time и end_time в секундах (timestamp)
    15 и 30 это поправка на лунные циклы (маятник фуко) для фильтра шума.
    Возвращает (dog_ts, cat_ts, manul_ts) в секундах.
    """
    tf_15 = 15 * tf_minutes * 60
    tf_30 = 30 * tf_minutes * 60
    tf_1 = 2.3333 * tf_minutes * 60
    
    FirstTimeGAS3 = idx2 + (idx2 - idx1)
    
    FirstGasCorrect15 = idx1 + tf_15
    FirstFakeGAS15diff = abs(FirstTimeGAS3 - FirstGasCorrect15) / 2
    FirstFakeGAS15 = FirstTimeGAS3 + tf_1 + FirstFakeGAS15diff
    
    FirstGasCorrect30 = idx1 + tf_30
    FirstGas30diff = abs(FirstTimeGAS3 - FirstGasCorrect30) / 2
    FirstGas30 = FirstTimeGAS3 + tf_1 + FirstGas30diff
    
    FirstGas23diff = (FirstGas30 - FirstFakeGAS15) / 2
    FirstGas23 = round(FirstFakeGAS15 + FirstGas23diff)
    
    FirstTimeGAS4 = FirstTimeGAS3 + (FirstTimeGAS3 - idx1)
    FirstMiddleGAS = FirstTimeGAS3 + (FirstTimeGAS3 - idx2)
    
    FirstEchoGASdiff15 = abs(FirstMiddleGAS - FirstGasCorrect15) / 2
    FirstEchoGAS15 = FirstTimeGAS4 + FirstEchoGASdiff15
    
    FirstEchoGASdiff30 = abs(FirstMiddleGAS - FirstGasCorrect30) / 2
    FirstEchoGAS30 = FirstTimeGAS4 + FirstEchoGASdiff30
    
    FirstEchoGASdiff23 = (FirstEchoGAS30 - FirstEchoGAS15) / 2
    FirstEchoGAS23 = round(FirstEchoGAS15 + FirstEchoGASdiff23)
    
    FirstFinalGASdiff23 = (FirstEchoGAS23 - FirstGas23) / 2
    FirstFinalGAS23 = round(FirstGas23 + FirstFinalGASdiff23)
    
    FirstEndGASdiff = abs(FirstEchoGAS23 - FirstFinalGAS23) / 2
    FirstEndGAS = round(FirstFinalGAS23 + FirstEndGASdiff)
    
    FirstEndGASdiff19 = abs(FirstFinalGAS23 - FirstGas23) / 2
    FirstEndGAS19 = round(FirstGas23 + FirstEndGASdiff19)
    
    return FirstGas23, FirstEndGAS, FirstEndGAS19   # dog, cat, manul
# FIX: Qt Platform Plugin Error
# ============================================================
def fix_qt_plugin():
    """Исправляет ошибку с Qt плагинами"""
    try:
        import PyQt5
        
        # Получаем путь к PyQt5
        pyqt_path = os.path.dirname(PyQt5.__file__)
        print(f"[QT] PyQt5 установлен в: {pyqt_path}")
        
        # Ищем папку с плагинами
        possible_plugin_paths = [
            os.path.join(pyqt_path, 'Qt', 'plugins'),
            os.path.join(pyqt_path, 'plugins'),
            os.path.join(pyqt_path, 'Qt5', 'plugins'),
            os.path.join(sys.prefix, 'Library', 'plugins'),
            os.path.join(sys.prefix, 'lib', 'site-packages', 'PyQt5', 'Qt', 'plugins'),
        ]
        
        found_path = None
        for path in possible_plugin_paths:
            platforms_path = os.path.join(path, 'platforms')
            if os.path.exists(platforms_path) and os.path.exists(os.path.join(platforms_path, 'qwindows.dll')):
                found_path = path
                print(f"[QT] Найден путь к плагинам: {found_path}")
                break
        
        if found_path:
            os.environ['QT_QPA_PLATFORM_PLUGIN_PATH'] = found_path
            print(f"[QT] Установлен QT_QPA_PLATFORM_PLUGIN_PATH = {found_path}")
            return True
        
        # Если не нашли, пробуем рекурсивный поиск
        import glob
        search_pattern = os.path.join(pyqt_path, '**', 'qwindows.dll')
        found = glob.glob(search_pattern, recursive=True)
        if found:
            plugin_dir = os.path.dirname(found[0])
            os.environ['QT_QPA_PLATFORM_PLUGIN_PATH'] = plugin_dir
            print(f"[QT] Найден qwindows.dll в: {plugin_dir}")
            return True
            
    except Exception as e:
        print(f"[QT] Ошибка: {e}")
    
    return False

# Вызываем функцию
fix_qt_plugin()

# Также добавляем путь к переменной окружения для Windows
if sys.platform == 'win32':
    # Добавляем путь к PyQt5 в PATH (для qwindows.dll)
    try:
        import PyQt5
        pyqt_path = os.path.dirname(PyQt5.__file__)
        qt_bin_path = os.path.join(pyqt_path, 'Qt', 'bin')
        if os.path.exists(qt_bin_path):
            os.environ['PATH'] = qt_bin_path + os.pathsep + os.environ.get('PATH', '')
            print(f"[QT] Добавлен в PATH: {qt_bin_path}")
    except:
        pass

class SkynetSplashScreen(QtWidgets.QDialog):
    """Анимированная заставка (без фона)"""
    def __init__(self, parent=None, duration_ms=5000):
        super().__init__(parent)
        
        self.setWindowFlags(
            QtCore.Qt.WindowType.FramelessWindowHint | 
            QtCore.Qt.WindowType.WindowStaysOnTopHint
        )
        self.setAttribute(QtCore.Qt.WidgetAttribute.WA_TranslucentBackground)
        
        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        
        self.label = QtWidgets.QLabel()
        self.label.setScaledContents(True)
        layout.addWidget(self.label)
        
        # Загружаем GIF
        current_dir = os.path.dirname(os.path.abspath(__file__))
        gif_path = os.path.join(current_dir, "giflogoskynet.gif")
        
        self.frames = []
        self.current_frame = 0
        
        if os.path.exists(gif_path):
            try:
                from PIL import Image
                gif = Image.open(gif_path)
                
                for frame_num in range(gif.n_frames):
                    try:
                        gif.seek(frame_num)
                        # Сохраняем прозрачность
                        if gif.mode == 'P':
                            frame = gif.convert('RGBA')
                        else:
                            frame = gif.convert('RGBA')
                        
                        data = frame.tobytes("raw", "RGBA")
                        qimage = QtGui.QImage(data, frame.width, frame.height, QtGui.QImage.Format_RGBA8888)
                        pixmap = QtGui.QPixmap.fromImage(qimage)
                        
                        if not pixmap.isNull():
                            scaled = pixmap.scaled(960, 960,
                                QtCore.Qt.AspectRatioMode.KeepAspectRatio,
                                QtCore.Qt.TransformationMode.SmoothTransformation)
                            self.frames.append(scaled)
                    except:
                        continue
                
                if self.frames:
                    self.label.setPixmap(self.frames[0])
                    self.animation_timer_id = self.startTimer(40)
            except Exception as e:
                print(f"[ЗАСТАВКА] Ошибка: {e}")
        else:
            print(f"[ЗАСТАВКА] Файл не найден")
        
        self.resize(1000, 1000)
        screen = QtWidgets.QApplication.primaryScreen().geometry()
        self.move(screen.center() - self.rect().center())
        
        self.close_timer = QtCore.QTimer()
        self.close_timer.setSingleShot(True)
        self.close_timer.timeout.connect(self.close)
        self.close_timer.start(duration_ms)
    
    def timerEvent(self, event):
        if self.frames:
            self.current_frame = (self.current_frame + 1) % len(self.frames)
            self.label.setPixmap(self.frames[self.current_frame])
    
    def closeEvent(self, event):
        if hasattr(self, 'animation_timer_id'):
            self.killTimer(self.animation_timer_id)
        if hasattr(self, 'close_timer'):
            self.close_timer.stop()
        event.accept()

import sys
import numpy as np
from datetime import datetime, timedelta
from PyQt5 import QtCore
from clickhouse_driver import Client as ClickHouseClient

class QualifierLinesGenerator(QtCore.QThread):
    """Генератор линий-квалификаторов (long_start, long_end, short_start, short_end)"""
    finished_signal = QtCore.pyqtSignal(dict)  # {'timeframe': count}
    error_signal = QtCore.pyqtSignal(str)
    progress_signal = QtCore.pyqtSignal(int, int)
    status_signal = QtCore.pyqtSignal(str)
    log_signal = QtCore.pyqtSignal(str)

    def __init__(self, ch_config, timeframe, start_dt=None, end_dt=None):
        """
        ch_config: dict с параметрами подключения ClickHouse (host, port, user, password)
        timeframe: '30m', '1h', '4h' (1m не поддерживается)
        start_dt, end_dt: если заданы – инкрементальный режим (только этот диапазон)
        """
        super().__init__()
        self.ch_config = ch_config
        self.timeframe = timeframe
        self.start_dt = start_dt
        self.end_dt = end_dt
        self._is_running = True
        self._client = None  # будет создан в run

    def run(self):
        # Проверка: 1m не поддерживается
        if self.timeframe == '1m':
            self.log_signal.emit(f"[QUALIFIER] Таймфрейм 1m не поддерживается, пропускаем")
            self.finished_signal.emit({self.timeframe: 0})
            return

        try:
            self.log_signal.emit(f"[QUALIFIER] Начало генерации для {self.timeframe}")

            # Создаём ОТДЕЛЬНОЕ соединение для этого воркера
            self._client = ClickHouseClient(
                host=self.ch_config['host'],
                port=self.ch_config['port'],
                user=self.ch_config['user'],
                password=self.ch_config['password'],
                settings={'insert_block_size': 1000, 'connect_timeout': 10}
            )
            self.log_signal.emit(f"[QUALIFIER] Создано отдельное соединение ClickHouse для {self.timeframe}")

            self._ensure_table()

            # Определяем диапазон
            if self.start_dt and self.end_dt:
                # Инкрементальный режим – удаляем старые записи в этом диапазоне
                self._client.execute(
                    f"ALTER TABLE crypto_data.qualifier_lines DELETE WHERE timeframe = '{self.timeframe}' "
                    f"AND timestamp >= '{self.start_dt.strftime('%Y-%m-%d %H:%M:%S')}' "
                    f"AND timestamp <= '{self.end_dt.strftime('%Y-%m-%d %H:%M:%S')}'"
                )
                self.log_signal.emit(f"[QUALIFIER] Удалены старые записи для диапазона {self.start_dt} – {self.end_dt}")
            else:
                # Полный пересчёт – удаляем все для этого таймфрейма
                self._client.execute(f"ALTER TABLE crypto_data.qualifier_lines DELETE WHERE timeframe = '{self.timeframe}'")
                # Определяем минимальную и максимальную дату из shifted_points
                rows = self._client.execute(
                    f"SELECT min(timestamp), max(timestamp) FROM crypto_data.shifted_points WHERE timeframe = '{self.timeframe}'"
                )
                if rows and rows[0][0] and rows[0][1]:
                    self.start_dt = rows[0][0]
                    self.end_dt = rows[0][1]
                    self.log_signal.emit(f"[QUALIFIER] Полный пересчёт для {self.timeframe}, диапазон {self.start_dt} – {self.end_dt}")
                else:
                    self.log_signal.emit(f"[QUALIFIER] Нет данных в shifted_points для {self.timeframe}, пропускаем")
                    self.finished_signal.emit({self.timeframe: 0})
                    return

            if not self.start_dt or not self.end_dt:
                self.log_signal.emit(f"[QUALIFIER] Нет диапазона для {self.timeframe}, пропускаем")
                self.finished_signal.emit({self.timeframe: 0})
                return

            # Загружаем все точки shifted_points для этого ТФ и диапазона
            query = f"""
                SELECT timestamp, shift_type
                FROM crypto_data.shifted_points
                WHERE timeframe = '{self.timeframe}'
                  AND timestamp >= '{self.start_dt.strftime('%Y-%m-%d %H:%M:%S')}'
                  AND timestamp <= '{self.end_dt.strftime('%Y-%m-%d %H:%M:%S')}'
                ORDER BY timestamp
            """
            points = self._client.execute(query)
            if not points:
                self.log_signal.emit(f"[QUALIFIER] Нет точек shifted_points для {self.timeframe} в диапазоне")
                self.finished_signal.emit({self.timeframe: 0})
                return

            self.log_signal.emit(f"[QUALIFIER] Загружено {len(points)} точек для {self.timeframe}")

            # Группируем по типу для массовой вставки
            insert_data = []
            # Кэш для цен (чтобы не делать запрос на каждую точку)
            cache_prices = {}
            cache_prev_open = {}

            def get_prev_open(ts):
                if ts in cache_prev_open:
                    return cache_prev_open[ts]
                query = f"""
                    SELECT open FROM crypto_data.btc_usdt_{self.timeframe}
                    WHERE timestamp < '{ts.strftime('%Y-%m-%d %H:%M:%S')}'
                    ORDER BY timestamp DESC LIMIT 1
                """
                rows = self._client.execute(query)
                val = float(rows[0][0]) if rows else None
                cache_prev_open[ts] = val
                return val

            def get_close(ts):
                if ts in cache_prices:
                    return cache_prices[ts]
                query = f"""
                    SELECT close FROM crypto_data.btc_usdt_{self.timeframe}
                    WHERE timestamp = '{ts.strftime('%Y-%m-%d %H:%M:%S')}'
                """
                rows = self._client.execute(query)
                val = float(rows[0][0]) if rows else None
                cache_prices[ts] = val
                return val

            # Фильтруем только нужные типы
            target_types = {'long_start', 'long_end', 'short_start', 'short_end'}
            filtered = [(ts, stype) for ts, stype in points if stype in target_types]

            self.log_signal.emit(f"[QUALIFIER] Из них целевых типов: {len(filtered)}")

            total = len(filtered)
            processed = 0
            batch_size = 5000

            for ts, stype in filtered:
                if not self._is_running:
                    break

                price = None
                if stype in ('long_start', 'short_start'):
                    price = get_close(ts)
                elif stype in ('long_end', 'short_end'):
                    price = get_prev_open(ts)

                if price is None:
                    continue

                insert_data.append((ts, self.timeframe, stype, price))
                processed += 1

                if len(insert_data) >= batch_size:
                    self._save_batch(insert_data)
                    insert_data.clear()
                    self.progress_signal.emit(processed, total)
                    self.status_signal.emit(f"[QUALIFIER] {self.timeframe}: {processed}/{total}")

            if insert_data:
                self._save_batch(insert_data)

            self.log_signal.emit(f"[QUALIFIER] Генерация для {self.timeframe} завершена, вставлено {processed} записей")
            self.finished_signal.emit({self.timeframe: processed})

        except Exception as e:
            self.log_signal.emit(f"[QUALIFIER] Ошибка: {str(e)}")
            import traceback
            self.log_signal.emit(traceback.format_exc())
            self.error_signal.emit(str(e))
        finally:
            if self._client:
                try:
                    self._client.disconnect()
                    self.log_signal.emit(f"[QUALIFIER] Соединение закрыто для {self.timeframe}")
                except Exception as e:
                    self.log_signal.emit(f"[QUALIFIER] Ошибка при закрытии соединения: {str(e)}")

    def _ensure_table(self):
        """Создаёт таблицу, если её нет"""
        self._client.execute("""
            CREATE TABLE IF NOT EXISTS crypto_data.qualifier_lines (
                timestamp DateTime,
                timeframe String,
                line_type String,
                price Float64
            ) ENGINE = MergeTree()
            ORDER BY (timeframe, timestamp)
        """)

    def _save_batch(self, batch):
        """Вставка пакета в ClickHouse"""
        self._client.execute(
            "INSERT INTO crypto_data.qualifier_lines (timestamp, timeframe, line_type, price) VALUES",
            batch
        )

    def stop(self):
        self._is_running = False
        self.log_signal.emit("[QUALIFIER] Остановка по запросу")

class MatcherFullShiftedWorker(QtCore.QThread):
    """Полное сопоставление для всех ID из 4h: находит сдвинутые точки и записывает в auto_ids для 1h и 30m."""
    finished_signal = QtCore.pyqtSignal(dict)   # {timeframe: count}
    error_signal = QtCore.pyqtSignal(str)
    progress_signal = QtCore.pyqtSignal(int, int)  # current, total
    status_signal = QtCore.pyqtSignal(str)         # детальный статус
    log_signal = QtCore.pyqtSignal(str)

    def __init__(self, ch_config, source_timeframe='4h', target_timeframes=None, chunk_size=50000):
        super().__init__()
        self.ch_config = ch_config
        self.source_tf = source_timeframe
        self.target_tfs = target_timeframes or ['1h', '30m']
        self.chunk_size = chunk_size
        self._is_running = True
        self._client = None
        self._start_time = None
        self._total = 0
        self._processed = 0

    def run(self):
        try:
            self._client = ClickHouseClient(
                host=self.ch_config['host'],
                port=self.ch_config['port'],
                user=self.ch_config['user'],
                password=self.ch_config['password'],
                settings={'insert_block_size': 10000, 'connect_timeout': 30}
            )
            self.log_signal.emit("[FULL-MATCHER] Загрузка ID из 4h...")
            self.status_signal.emit("Загрузка ID из 4h...")

            # 1. Загружаем все ID из 4h
            query_ids = f"""
                SELECT id, start_time, end_time, direction
                FROM crypto_data.auto_ids
                WHERE timeframe = '{self.source_tf}'
                ORDER BY id
            """
            all_ids = self._client.execute(query_ids)
            self._total = len(all_ids)
            self.log_signal.emit(f"[FULL-MATCHER] Загружено {self._total} ID из 4h")
            self.status_signal.emit(f"Загружено {self._total} ID из 4h")

            # 2. Загружаем пересечения для целевых ТФ (в числах)
            intersections = {}
            for tf in self.target_tfs:
                query = f"""
                    SELECT timestamp, intersection_type, (price1 + price2)/2 AS price
                    FROM crypto_data.qualifier_intersections
                    WHERE timeframe = '{tf}'
                    ORDER BY timestamp
                """
                rows = self._client.execute(query)
                tf_data = {}
                for ts, inter_type, price in rows:
                    ts_sec = int(ts.timestamp())
                    tf_data.setdefault(inter_type, []).append((ts_sec, float(price)))
                for inter_type in tf_data:
                    tf_data[inter_type].sort(key=lambda x: x[0])
                intersections[tf] = tf_data
                self.log_signal.emit(f"[FULL-MATCHER] Загружено {len(rows)} пересечений для {tf} (в числах)")

            # 3. Загружаем сдвинутые точки (в числах)
            shifted_cache = {}
            for tf in self.target_tfs:
                query = f"""
                    SELECT timestamp, shift_type
                    FROM crypto_data.shifted_points
                    WHERE timeframe = '{tf}'
                """
                rows = self._client.execute(query)
                tf_shifted = {}
                for ts, stype in rows:
                    ts_sec = int(ts.timestamp())
                    tf_shifted.setdefault(stype, []).append(ts_sec)
                for stype in tf_shifted:
                    tf_shifted[stype].sort()
                shifted_cache[tf] = tf_shifted
                self.log_signal.emit(f"[FULL-MATCHER] Загружено {len(rows)} сдвинутых точек для {tf} (в числах)")

            # 4. Удаляем старые записи для целевых ТФ
            for tf in self.target_tfs:
                self._client.execute(f"ALTER TABLE crypto_data.auto_ids DELETE WHERE timeframe = '{tf}'")
                self.log_signal.emit(f"[FULL-MATCHER] Старые записи для {tf} удалены")

            # 5. Обработка ID чанками
            buffers = {tf: [] for tf in self.target_tfs}
            batch_size = 5000
            total_inserted = {tf: 0 for tf in self.target_tfs}
            self._processed = 0
            self._start_time = time.time()

            total_chunks = (self._total + self.chunk_size - 1) // self.chunk_size
            self.log_signal.emit(f"[FULL-MATCHER] Начинается обработка {total_chunks} чанков по {self.chunk_size} ID...")
            self.status_signal.emit(f"Начинается обработка {total_chunks} чанков...")

            for chunk_idx in range(total_chunks):
                if not self._is_running:
                    break
                start_idx = chunk_idx * self.chunk_size
                end_idx = min(start_idx + self.chunk_size, self._total)
                chunk = all_ids[start_idx:end_idx]
                self.log_signal.emit(f"[FULL-MATCHER] Обработка чанка {chunk_idx+1}/{total_chunks} (ID {start_idx+1}-{end_idx})")
                self.status_signal.emit(f"Чанк {chunk_idx+1}/{total_chunks}...")

                chunk_start_time = time.time()
                self._process_chunk(chunk, intersections, shifted_cache, buffers, total_inserted, batch_size)
                self._processed += len(chunk)
                chunk_elapsed = time.time() - chunk_start_time

                self.log_signal.emit(
                    f"[FULL-MATCHER] Чанк {chunk_idx+1}/{total_chunks}: ID={len(chunk)}, "
                    f"время={chunk_elapsed:.2f} сек"
                )

                self._update_status()
                self.progress_signal.emit(self._processed, self._total)

            # Вставляем остатки
            for tf in self.target_tfs:
                if buffers[tf]:
                    self._flush_buffer(tf, buffers[tf])
                    total_inserted[tf] += len(buffers[tf])
                    buffers[tf].clear()

            self.log_signal.emit(f"[FULL-MATCHER] Завершено. Вставлено: {total_inserted}")
            self.status_signal.emit(f"✅ Завершено! Вставлено: {total_inserted}")
            self.finished_signal.emit(total_inserted)

        except Exception as e:
            self.error_signal.emit(str(e))
            import traceback
            self.log_signal.emit(traceback.format_exc())
        finally:
            if self._client:
                try:
                    self._client.disconnect()
                except:
                    pass

    def _process_chunk(self, chunk, intersections, shifted_cache, buffers, total_inserted, batch_size):
        """Обрабатывает один чанк ID."""
        tf_minutes_map = {'1h': 60, '30m': 30}
        for row in chunk:
            if not self._is_running:
                break
            id_val, start_dt, end_dt, direction = row
            start_sec = int(start_dt.timestamp())
            end_sec = int(end_dt.timestamp())

            for tf in self.target_tfs:
                tf_minutes = tf_minutes_map.get(tf, 60)

                # Находим первую и вторую точки через пересечения
                first_ts, first_price = self._find_extreme_in_range(
                    intersections[tf].get('long_start_short_end_down' if direction == 'long' else 'short_start_long_end_up', []),
                    start_sec,
                    start_sec + 9 * 3600,  # 9 часов в секундах
                    'max' if direction == 'long' else 'min'
                )
                if first_ts is None:
                    continue

                second_ts, second_price = self._find_extreme_in_range(
                    intersections[tf].get('short_start_long_end_up' if direction == 'long' else 'long_start_short_end_down', []),
                    end_sec - 9 * 3600,
                    end_sec,
                    'min' if direction == 'long' else 'max'
                )
                if second_ts is None:
                    continue

                # Теперь находим сдвинутые точки
                shifted1_ts = self._find_nearest_shifted(
                    shifted_cache[tf].get('long_start' if direction == 'long' else 'short_start', []),
                    first_ts,
                    tf_minutes,
                    max_bars=3,
                    search_direction='left'
                )
                shifted2_ts = self._find_nearest_shifted(
                    shifted_cache[tf].get('long_end' if direction == 'long' else 'short_end', []),
                    second_ts,
                    tf_minutes,
                    max_bars=3,
                    search_direction='right'
                )

                if shifted1_ts is None or shifted2_ts is None:
                    continue

                # Преобразуем числа обратно в datetime
                shifted1_dt = datetime.fromtimestamp(shifted1_ts)
                shifted2_dt = datetime.fromtimestamp(shifted2_ts)

                # Добавляем в буфер
                buffers[tf].append((
                    id_val,
                    tf,
                    shifted1_dt,
                    shifted2_dt,
                    direction,
                    'BTC/USDT',
                    'UTC+10',
                    datetime.now()
                ))

                if len(buffers[tf]) >= batch_size:
                    self._flush_buffer(tf, buffers[tf])
                    total_inserted[tf] += len(buffers[tf])
                    buffers[tf].clear()

    def _find_extreme_in_range(self, points, start_sec, end_sec, extreme):
        """Ищет точку с экстремальной ценой (max или min) среди points в интервале [start_sec, end_sec]."""
        if not points:
            return None, None
        import bisect
        timestamps = [p[0] for p in points]
        left = bisect.bisect_left(timestamps, start_sec)
        right = bisect.bisect_right(timestamps, end_sec)
        if left >= right:
            return None, None
        if extreme == 'max':
            best_idx = max(range(left, right), key=lambda i: points[i][1])
        else:
            best_idx = min(range(left, right), key=lambda i: points[i][1])
        return points[best_idx][0], points[best_idx][1]

    def _find_nearest_shifted(self, timestamps, target_sec, tf_minutes, max_bars=3, search_direction='left'):
        """
        Ищет ближайшую сдвинутую точку (timestamp в секундах) относительно target_sec в пределах max_bars свечей.
        timestamps - отсортированный список чисел.
        """
        if not timestamps:
            return None
        delta_sec = max_bars * tf_minutes * 60
        import bisect
        idx = bisect.bisect_left(timestamps, target_sec)

        best_ts = None
        best_diff = float('inf')

        # Проверяем влево
        i = idx - 1
        while i >= 0:
            diff = timestamps[i] - target_sec
            if abs(diff) > delta_sec:
                break
            if search_direction == 'left' and diff > 0:
                i -= 1
                continue
            if search_direction == 'right' and diff < 0:
                i -= 1
                continue
            if abs(diff) < best_diff:
                best_diff = abs(diff)
                best_ts = timestamps[i]
            i -= 1

        # Проверяем вправо
        i = idx
        while i < len(timestamps):
            diff = timestamps[i] - target_sec
            if abs(diff) > delta_sec:
                break
            if search_direction == 'left' and diff > 0:
                i += 1
                continue
            if search_direction == 'right' and diff < 0:
                i += 1
                continue
            if abs(diff) < best_diff:
                best_diff = abs(diff)
                best_ts = timestamps[i]
            i += 1

        return best_ts

    def _flush_buffer(self, timeframe, buffer):
        """Вставка пакета записей в auto_ids."""
        if not buffer:
            return
        self._client.execute(
            "INSERT INTO crypto_data.auto_ids (id, timeframe, start_time, end_time, direction, instrument, timezone, created_at) VALUES",
            buffer
        )
        self.log_signal.emit(f"[FULL-MATCHER] Вставлено {len(buffer)} записей для {timeframe}")

    def _update_status(self):
        """Обновляет статус с информацией о скорости и оставшемся времени."""
        if self._total == 0 or self._processed == 0:
            return
        elapsed = time.time() - self._start_time
        rate = self._processed / elapsed if elapsed > 0 else 0
        remaining = self._total - self._processed
        eta_seconds = remaining / rate if rate > 0 else 0
        eta_min = int(eta_seconds // 60)
        eta_sec = int(eta_seconds % 60)
        if eta_seconds > 0:
            eta_str = f"{eta_min}м {eta_sec:02d}с"
        else:
            eta_str = "оценивается..."
        pct = (self._processed / self._total) * 100
        self.status_signal.emit(
            f"Обработано: {self._processed}/{self._total} ({pct:.1f}%) | "
            f"Скорость: {rate:.1f} ID/сек | ETA: {eta_str}"
        )

    def stop(self):
        self._is_running = False
        self.log_signal.emit("[FULL-MATCHER] Остановка по запросу")

class QualifierMarkersWorker(QtCore.QThread):
    finished_signal = QtCore.pyqtSignal(list)  # [(timestamp_ms, price, line_type), ...]
    error_signal = QtCore.pyqtSignal(str)

    def __init__(self, ch_client, timeframe, start_dt=None, end_dt=None):
        super().__init__()
        self.ch_client = ch_client
        self.timeframe = timeframe
        self.start_dt = start_dt
        self.end_dt = end_dt

    def run(self):
        try:
            query = f"""
                SELECT timestamp, price, line_type
                FROM crypto_data.qualifier_lines
                WHERE timeframe = '{self.timeframe}'
            """
            if self.start_dt:
                query += f" AND timestamp >= '{self.start_dt.strftime('%Y-%m-%d %H:%M:%S')}'"
            if self.end_dt:
                query += f" AND timestamp <= '{self.end_dt.strftime('%Y-%m-%d %H:%M:%S')}'"
            query += " ORDER BY timestamp"

            rows = self.ch_client.execute(query)
            result = []
            for ts, price, line_type in rows:
                result.append((ts.timestamp() * 1000, price, line_type))
            self.finished_signal.emit(result)
        except Exception as e:
            self.error_signal.emit(str(e))

class AntiIdBuilderWorker(QtCore.QThread):
    finished_signal = QtCore.pyqtSignal(dict)
    error_signal = QtCore.pyqtSignal(str)
    progress_signal = QtCore.pyqtSignal(int, int)
    log_signal = QtCore.pyqtSignal(str)
    status_signal = QtCore.pyqtSignal(str)

    def __init__(self, ch_config, timeframe, max_bars=3):
        super().__init__()
        self.ch_config = ch_config
        self.timeframe = timeframe
        self.max_bars = max_bars
        self._is_running = True
        self._client = None

    def run(self):
        try:
            self._client = ClickHouseClient(
                host=self.ch_config['host'],
                port=self.ch_config['port'],
                user=self.ch_config['user'],
                password=self.ch_config['password'],
                settings={'insert_block_size': 100000, 'connect_timeout': 60}
            )

            self.log_signal.emit(f"[ANTI-ID] Загрузка ID из {self.timeframe}...")
            self.status_signal.emit("Загрузка ID...")

            # Загружаем все ID (кроме анти)
            query_ids = f"""
                SELECT id, start_time, end_time
                FROM crypto_data.auto_ids
                WHERE timeframe = '{self.timeframe}'
                  AND direction NOT IN ('antilong', 'antishort')
                ORDER BY id
            """
            rows = self._client.execute(query_ids)
            total = len(rows)
            if total == 0:
                self.error_signal.emit("Нет ID для обработки")
                return

            self.log_signal.emit(f"[ANTI-ID] Загружено {total} ID")
            self.status_signal.emit("Загрузка сдвинутых точек...")

            # Загружаем сдвинутые точки
            query_shifted = f"""
                SELECT toUnixTimestamp(timestamp) as ts, shift_type
                FROM crypto_data.shifted_points
                WHERE timeframe = '{self.timeframe}'
                ORDER BY ts
            """
            shifted_rows = self._client.execute(query_shifted)
            if not shifted_rows:
                self.error_signal.emit("Нет сдвинутых точек")
                return

            self.log_signal.emit(f"[ANTI-ID] Загружено {len(shifted_rows)} сдвинутых точек")

            import bisect
            # Разделяем по типам
            long_start = []
            long_end = []
            short_start = []
            short_end = []
            for ts, stype in shifted_rows:
                if stype == 'long_start':
                    long_start.append(ts)
                elif stype == 'long_end':
                    long_end.append(ts)
                elif stype == 'short_start':
                    short_start.append(ts)
                elif stype == 'short_end':
                    short_end.append(ts)

            self.log_signal.emit(f"[ANTI-ID] Распределено: long_start={len(long_start)}, "
                                 f"long_end={len(long_end)}, short_start={len(short_start)}, "
                                 f"short_end={len(short_end)}")

            # Удаляем старые анти-ID
            self._client.execute(
                f"ALTER TABLE crypto_data.auto_ids DELETE "
                f"WHERE timeframe = '{self.timeframe}' AND direction IN ('antilong', 'antishort')"
            )
            self.log_signal.emit("[ANTI-ID] Старые анти-ID удалены")

            tf_minutes = {'30m': 30, '1h': 60, '4h': 240}[self.timeframe]
            delta_sec = self.max_bars * tf_minutes * 60

            batch_size = 100000
            buffer = []
            total_inserted = 0
            start_time = time.time()

            self.status_signal.emit("Начинаем построение анти-ID...")

            for idx, (id_val, start_dt, end_dt) in enumerate(rows):
                if not self._is_running:
                    break

                start_ts = start_dt.timestamp()
                end_ts = end_dt.timestamp()

                # Поиск long_start
                pos = bisect.bisect_right(long_start, start_ts)
                best_ls = None
                if pos > 0:
                    cand = long_start[pos - 1]
                    if start_ts - cand <= delta_sec:
                        best_ls = cand

                # Поиск short_end
                pos = bisect.bisect_left(short_end, end_ts)
                best_se = None
                if pos < len(short_end):
                    cand = short_end[pos]
                    if cand - end_ts <= delta_sec:
                        best_se = cand

                if best_ls is not None and best_se is not None:
                    buffer.append((id_val, self.timeframe,
                                   datetime.fromtimestamp(best_ls),
                                   datetime.fromtimestamp(best_se),
                                   'antilong', 'BTC/USDT', 'UTC+10', datetime.now()))
                    total_inserted += 1

                # Поиск short_start
                pos = bisect.bisect_right(short_start, start_ts)
                best_ss = None
                if pos > 0:
                    cand = short_start[pos - 1]
                    if start_ts - cand <= delta_sec:
                        best_ss = cand

                # Поиск long_end
                pos = bisect.bisect_left(long_end, end_ts)
                best_le = None
                if pos < len(long_end):
                    cand = long_end[pos]
                    if cand - end_ts <= delta_sec:
                        best_le = cand

                if best_ss is not None and best_le is not None:
                    buffer.append((id_val, self.timeframe,
                                   datetime.fromtimestamp(best_ss),
                                   datetime.fromtimestamp(best_le),
                                   'antishort', 'BTC/USDT', 'UTC+10', datetime.now()))
                    total_inserted += 1

                if len(buffer) >= batch_size:
                    self._flush_buffer(buffer)
                    buffer.clear()

                # Прогресс и ETA каждые 10000 ID
                if idx % 10000 == 0 or idx == total - 1:
                    self.progress_signal.emit(idx + 1, total)
                    elapsed = time.time() - start_time
                    if elapsed > 0 and idx > 0:
                        rate = (idx + 1) / elapsed
                        remaining = total - (idx + 1)
                        eta = remaining / rate if rate > 0 else 0
                        eta_min = int(eta // 60)
                        eta_sec = int(eta % 60)
                        self.status_signal.emit(
                            f"Обработано {idx+1}/{total} ID, вставлено {total_inserted} анти-ID, "
                            f"скорость {rate:.1f} ID/сек, ETA {eta_min} мин {eta_sec} сек"
                        )

            if buffer:
                self._flush_buffer(buffer)

            elapsed_total = time.time() - start_time
            self.log_signal.emit(f"[ANTI-ID] Готово. Вставлено {total_inserted} анти-ID за {elapsed_total:.2f} сек")
            self.status_signal.emit(f"Готово! Вставлено {total_inserted} анти-ID за {elapsed_total:.2f} сек")
            self.finished_signal.emit({self.timeframe: total_inserted})

        except Exception as e:
            self.error_signal.emit(str(e))
            import traceback
            self.log_signal.emit(traceback.format_exc())
        finally:
            if self._client:
                try:
                    self._client.disconnect()
                except:
                    pass

    def _flush_buffer(self, buffer):
        if not buffer:
            return
        self._client.execute(
            "INSERT INTO crypto_data.auto_ids (id, timeframe, start_time, end_time, direction, instrument, timezone, created_at) VALUES",
            buffer
        )

    def stop(self):
        self._is_running = False
        self.log_signal.emit("[ANTI-ID] Остановка по запросу")

class AutoLimbDebugger(QtCore.QThread):
    finished_signal = QtCore.pyqtSignal(dict)
    error_signal = QtCore.pyqtSignal(str)
    log_signal = QtCore.pyqtSignal(str)
    progress_signal = QtCore.pyqtSignal(int)

    def __init__(self, ch_config, timeframe, target_id):
        """
        ch_config: dict с ключами host, port, user, password
        """
        super().__init__()
        self.ch_config = ch_config
        self.timeframe = timeframe
        self.target_id = target_id
        self._is_running = True
        self._client = None   # будет создан в run()

    def _get_impulse_type_and_subtype(self, id_val, timeframe):
        """
        Возвращает (impulse_type, subtype) для указанного ID и таймфрейма.
        Если данных нет, возвращает (None, None).
        Логирует результат.
        """
        try:
            query = f"""
                SELECT impulse_type, subtype
                FROM crypto_data.impulse_ids
                WHERE id = {id_val} AND timeframe = '{timeframe}'
                LIMIT 1
            """
            rows = self._client.execute(query)
            if rows:
                impulse_type, subtype = rows[0]
                self.log_signal.emit(
                    f"[ИМПУЛЬС-ТИП] ID {id_val} (ТФ {timeframe}): тип={impulse_type}, подтип={subtype}"
                )
                return impulse_type, subtype
            else:
                self.log_signal.emit(
                    f"[ИМПУЛЬС-ТИП] ID {id_val} (ТФ {timeframe}) не найден в impulse_ids"
                )
                return None, None
        except Exception as e:
            self.log_signal.emit(f"[ИМПУЛЬС-ТИП] Ошибка для ID {id_val}: {str(e)}")
            return None, None

    def _find_organ_right_point_non_inverted_max(self, start_dt, end_dt):
        """
        Ищет long_end с максимальным close (без ограничений).
        Используется как fallback.
        """
        query = f"""
            SELECT sp.timestamp, c.close
            FROM crypto_data.shifted_points sp
            JOIN crypto_data.btc_usdt_{self.timeframe} c ON sp.timestamp = c.timestamp
            WHERE sp.timeframe = '{self.timeframe}'
              AND sp.shift_type = 'long_end'
              AND sp.timestamp > '{start_dt.strftime('%Y-%m-%d %H:%M:%S')}'
              AND sp.timestamp <= '{end_dt.strftime('%Y-%m-%d %H:%M:%S')}'
            ORDER BY c.close DESC
            LIMIT 1
        """
        rows = self._client.execute(query)
        if not rows:
            return None, None
        best_ts, best_close = rows[0]
        prev_open = self._get_prev_open_at_time(best_ts)
        if prev_open is None:
            prev_open = best_close
        return best_ts, prev_open

    # -----------------------------------------------------------------
    # Служебные методы
    # -----------------------------------------------------------------
