    def stop_auto_id_builder(self):
        if hasattr(self, 'auto_id_worker') and self.auto_id_worker.isRunning():
            self.auto_id_worker.stop()
            self.btn_stop_auto_ids.setEnabled(False)
            self.btn_build_auto_ids.setEnabled(True)
            self.btn_build_auto_ids.setText("🤖 Построить авто-ID")
